function OSInfiniteListInit(buttonId, LoadMoreId, LoadingMoreId) {
    $('body').scroll(function() {
           if($('body').scrollTop() + $('body').height() > $(document).height() - ($('body').height() * 0.30)) {
               $('body').unbind('scroll');
               var button = $('#' + buttonId);
               var LoadMore = $('#' + LoadMoreId);
               var LoadingMore = $('#' + LoadingMoreId);

               $(LoadMore).toggle();
               $(LoadingMore).toggle();               
               button.click();               
           }
    });
}
